/* Level overlay code after gameplay/entities; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "asm.h"

typedef struct {
    char pad0[0x84];
    f32 lo;
    f32 hi;
} Range;

/* Sets the range to x plus or minus 0.2. */
void set_range_centered_on_value(Range *range, f32 x) __asm__("FUN_L01_0026eff8");

void set_range_centered_on_value(Range *range, f32 x) {
    range->lo = x - 0.2f;
    range->hi = x + 0.2f;
}
